export function nowIso() {
  return new Date().toISOString();
}

export function nowEpoch() {
  return Date.now();
}

files.lib/logger.js:
import { nowIso } from './clock.js';

export function log(msg) {
  console.log(`${nowIso()} ${msg}`);
}

files.lib/cache.js:
import { nowEpoch } from './clock.js';

export function fresh(entry) {
  return nowEpoch() - entry.t < 5000;
}

